    parts.push(
      <Text key={`txt-${lastIndex}`} style={{ color: colors.textSecondary }}>
        {text.slice(lastIndex)}
      </Text>
    );
  }

  return parts.length > 0 ? parts : [<Text key="full" style={{ color: colors.textSecondary }}>{text}</Text>];
