    flex: 1,
  },
  header: {
    flexDirection: "row",
    alignItems: "center",
    gap: 12,
  },
  searchBar: {
    flex: 1,
    flexDirection: "row",
    alignItems: "center",
    paddingHorizontal: 12,
    height: 44,
    borderRadius: 12,
    borderWidth: 1,
    gap: 8,
  },
  searchInput: {
    flex: 1,
    fontSize: 15,
    height: 44,
    padding: 0,
  },
  closeBtn: {
    width: 36,
    height: 36,
    borderRadius: 18,
    alignItems: "center",
    justifyContent: "center",
  },
  divider: {
    height: StyleSheet.hairlineWidth,
    marginTop: 12,
    marginBottom: 4,
  },
  resultsList: {
    marginTop: 4,
  },
  resultRow: {
    flexDirection: "row",
    alignItems: "center",
    paddingVertical: 12,
    paddingHorizontal: 4,
  },
  resultName: {
    fontFamily: "JetBrainsMono",
    fontSize: 15,
    fontWeight: "700",
  },
  resultModule: {
    fontFamily: "JetBrainsMono",
    fontSize: 12,
    marginTop: 2,
  },
  flex1: { flex: 1 },
  // Inline detail
  detailWrap: { flex: 1 },
  detailHeader: { flexDirection: "row", alignItems: "center", gap: 8, marginBottom: 8 },
  backBtn: { width: 36, height: 36, borderRadius: 18, alignItems: "center", justifyContent: "center" },
