  const LITERAL_RE = /\b(true|false|null|undefined|this|NaN|Infinity)\b/g;
  const P5_RE = new RegExp(`\\b(${P5_FUNCTION_NAMES.join("|")})\\b(?=\\s*\\()`, "g");
  const P5_DOT_RE = new RegExp(`(?<=\\.)(${P5_FUNCTION_NAMES.join("|")})\\b(?=\\s*\\()`, "g");
